import sys
from collections import deque
from math import inf

def rint():
	return map(int, sys.stdin.readline().split())

def bfs(sr, sc):
	global ans
	q = deque()
	q.append((x, y, sr, sc))
	visit[sr][sc] = 1
	ans += 1
	while q:
		(ll, rr, r, c) = q.popleft()
		nadj = []
		if r + 1 < n and maze[r + 1][c] == '.':
			nadj.append([r + 1, c])
		if r - 1 >= 0 and maze[r - 1][c] == '.':
			nadj.append([r - 1, c])
		if c + 1 < m and maze[r][c + 1] == '.':
			nadj.append([r, c + 1])
		if c - 1 >= 0 and maze[r][c - 1] == '.':
			nadj.append([r, c - 1])
		for (adr, adc) in nadj:
			if visit[adr][adc] == 1:
				continue
			if c == adc:
				visit[adr][adc] = 1
				ans += 1
				q.appendleft([ll, rr, adr, adc])
			elif adc < c:
				if ll - 1 >= 0:
					visit[adr][adc] = 1
					ans += 1
					q.append([ll - 1, rr, adr, adc])
			elif rr - 1 >= 0:
				visit[adr][adc] = 1
				ans += 1
				q.append([ll, rr - 1, adr, adc])
(n, m) = rint()
(sr, sc) = rint()
(x, y) = rint()
sr -= 1
sc -= 1
maze = []
for i in range(n):
	maze.append(input())
visit = [[0 for i in range(m)] for j in range(n)]
ans = 0
bfs(sr, sc)
print(ans)
